#!/usr/bin/env bash
set -euo pipefail
umask 077
exec python3 - "$0" "$@" <<'BELIAL_BOOTSTRAP_PY'
import argparse,base64,datetime,fcntl,hashlib,io,json,os,shutil,subprocess,sys,tarfile,tempfile,time
from pathlib import Path
PAYLOAD_SHA='631e7fd6ae795cd8639f11870b7d1e97f64e16709b4b1edcac136977f99204e2'
BASE_COMMIT='31040a0ae01ac93597095fa9af6c73772e5fa60c'
RELEASE='belial-a6-wide-2h-v1'
self_path=Path(sys.argv[1]).resolve()
p=argparse.ArgumentParser();p.add_argument('--verify-only',action='store_true');p.add_argument('--install-only',action='store_true');args=p.parse_args(sys.argv[2:])
def run(cmd,**kw):return subprocess.run(list(map(str,cmd)),check=True,**kw)
def output(cmd,**kw):return subprocess.check_output(list(map(str,cmd)),text=True,**kw).strip()
def safe(path):
    for q in (path,*path.parents):
        if q.is_symlink():raise RuntimeError('SYMLINK_REFUSED:'+str(q))
    return path
payload=base64.b64decode(self_path.read_bytes().split(b'\n__BELIAL_PAYLOAD__\n',1)[1],validate=False)
if hashlib.sha256(payload).hexdigest()!=PAYLOAD_SHA:raise RuntimeError('INSTALLER_PAYLOAD_HASH_MISMATCH')
with tempfile.TemporaryDirectory(prefix='belial-a6-') as temp:
    work=Path(temp)/'package';work.mkdir()
    with tarfile.open(fileobj=io.BytesIO(payload),mode='r:gz') as tar:
        for member in tar.getmembers():
            rel=Path(member.name)
            if rel.is_absolute() or '..' in rel.parts or member.issym() or member.islnk() or not (member.isdir() or member.isfile()):raise RuntimeError('UNSAFE_ARCHIVE_MEMBER')
            dest=work/rel
            if member.isdir():dest.mkdir(parents=True,exist_ok=True)
            else:
                dest.parent.mkdir(parents=True,exist_ok=True)
                with tar.extractfile(member) as source,dest.open('xb') as target:shutil.copyfileobj(source,target)
    env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',PYTHONPATH=str(work))
    print('[1/5] Verificando código completo, hashes e testes offline.',flush=True)
    run([sys.executable,'-B','-m','a6.verify'],cwd=work,env=env)
    if args.verify_only:print('BELIAL_A6_VERIFY_ONLY=PASS');raise SystemExit(0)
    if os.geteuid()==0:raise RuntimeError('EXECUTE_COM_USUARIO_NORMAL_SEM_SUDO')
    base=Path('/mnt/sherlock-ssd/Bot Belial/Belial Negro/Raydium Hunter')
    repo=Path(os.environ.get('BELIAL_GIT_REPO','/home/hobit/Área de trabalho/belial-github-publicar'))
    downloads=Path('/home/hobit/Downloads');safe(base);safe(repo);safe(downloads)
    if not Path('/mnt/sherlock-ssd').is_mount():raise RuntimeError('SSD_NOT_MOUNTED')
    if not base.is_dir() or not (repo/'.git').exists():raise RuntimeError('BELIAL_BASE_OR_GIT_REPO_MISSING')
    for cmd in ('git','systemctl','systemd-run','cargo'):
        if shutil.which(cmd) is None:raise RuntimeError('DEPENDENCY_MISSING:'+cmd)
    run(['git','-C',repo,'cat-file','-e',BASE_COMMIT+'^{commit}'])
    # Resolve configured identity before creating a worktree; never fabricate authorship.
    output(['git','-C',repo,'var','GIT_AUTHOR_IDENT'])
    runtime=safe(base/'runtime/belial-a6');runtime.mkdir(parents=True,exist_ok=True)
    lock=(runtime/'install.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
    backup=safe(base/'.belial-backups'/('a6-install-'+stamp));backup.mkdir(parents=True)
    (backup/'PREVIOUS_GIT_HEAD.txt').write_text(output(['git','-C',repo,'rev-parse','HEAD'])+'\n')
    prior=base/'runtime/belial-a51r/ACTIVE_RUN.json'
    if prior.is_file():shutil.copyfile(prior,backup/'A51R_ACTIVE_RUN_BEFORE.json')
    destination=safe(base/'releases'/RELEASE);destination.parent.mkdir(parents=True,exist_ok=True)
    print('[2/5] Instalando release A6 separada; preservando a execução atual.',flush=True)
    if destination.exists():
        installed_env=dict(env,PYTHONPATH=str(destination))
        run([sys.executable,'-B','-m','a6.verify','--hashes-only'],cwd=destination,env=installed_env)
        if (destination/'A6_MANIFEST_SHA256.json').read_bytes()!=(work/'A6_MANIFEST_SHA256.json').read_bytes():raise RuntimeError('EXISTING_A6_RELEASE_DIFFERS_NO_OVERWRITE')
    else:
        stage=Path(tempfile.mkdtemp(prefix='.a6-staging-',dir=destination.parent))
        try:shutil.copytree(work,stage,dirs_exist_ok=True);stage.rename(destination)
        finally:
            if stage.exists():shutil.rmtree(stage)
    print('[3/5] Continuidade Git em branch própria.',flush=True)
    manifest_hash=hashlib.sha256((work/'A6_MANIFEST_SHA256.json').read_bytes()).hexdigest()
    branch='work/belial-a6-2h-'+manifest_hash[:12];checkout=safe(runtime/'git-worktrees'/manifest_hash[:12]);checkout.parent.mkdir(exist_ok=True)
    snaprel=Path('Belial Negro/Raydium Hunter/source-snapshots')/RELEASE
    installerrel=Path('Belial Negro/Raydium Hunter/installers')/self_path.name
    if not checkout.exists():
        run(['git','-C',repo,'worktree','add','-b',branch,checkout,BASE_COMMIT])
        snap=checkout/snaprel;shutil.copytree(destination,snap)
        installer=(checkout/installerrel);installer.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(self_path,installer)
        shutil.copyfile(work/'docs/HANDOFF_A6_WIDE_2H_V1.md',checkout/'docs/HANDOFF_A6_WIDE_2H_V1.md')
        (checkout/'docs/CURRENT_STATE.md').write_text((work/'docs/HANDOFF_A6_WIDE_2H_V1.md').read_text())
        checkpoint=checkout/'Belial Negro/Raydium Hunter/manifests/CHECKPOINT_A6_WIDE_2H.json';checkpoint.parent.mkdir(parents=True,exist_ok=True)
        checkpoint.write_text(json.dumps(dict(base_commit=BASE_COMMIT,release=RELEASE,package_sha256=manifest_hash,installer_sha256=hashlib.sha256(self_path.read_bytes()).hexdigest(),orders=False,native_gpu_validation='EXECUTED_ON_PC_BEFORE_CAPTURE',capture_completed=False),indent=2)+'\n')
        run(['git','-C',checkout,'add','-f','--',snaprel,installerrel,'docs/HANDOFF_A6_WIDE_2H_V1.md','docs/CURRENT_STATE.md',checkpoint.relative_to(checkout)])
        # Compare staged source blobs, not merely the working tree, before commit.
        staged=json.loads((work/'A6_MANIFEST_SHA256.json').read_text())['files']
        for rel,expected in staged.items():
            raw=subprocess.check_output(['git','-C',str(checkout),'show',':'+str(snaprel/rel)])
            if hashlib.sha256(raw).hexdigest()!=expected:raise RuntimeError('STAGED_SOURCE_HASH_MISMATCH:'+rel)
        run(['git','-C',checkout,'commit','-m','feat(a6): isolated wide discovery and causal two-hour paper laboratory'])
    else:
        if output(['git','-C',checkout,'status','--porcelain']):raise RuntimeError('A6_WORKTREE_NOT_CLEAN:'+str(checkout))
        if (checkout/snaprel/'A6_MANIFEST_SHA256.json').read_bytes()!=(work/'A6_MANIFEST_SHA256.json').read_bytes():raise RuntimeError('A6_GIT_CHECKPOINT_MISMATCH')
    commit=output(['git','-C',checkout,'rev-parse','HEAD'])
    git_state=dict(branch=branch,commit=commit,checkout=str(checkout),base_commit=BASE_COMMIT,package_sha256=manifest_hash,orders=False)
    try:
        run(['git','-C',checkout,'push','-u','origin','HEAD:refs/heads/'+branch],timeout=90)
        git_state['remote_synced']=True
    except (subprocess.CalledProcessError,subprocess.TimeoutExpired):
        git_state['remote_synced']=False;print('A6_GIT_PUSH_PENDENTE: commit local preservado; repetir git push na branch indicada.',flush=True)
    (runtime/'GIT_CHECKPOINT.json').write_text(json.dumps(git_state,indent=2)+'\n');print('A6_GIT_COMMIT='+commit,flush=True);print('A6_GIT_BRANCH='+branch,flush=True)
    if args.install_only:print('A6_INSTALLED_NO_CAPTURE_REQUESTED');raise SystemExit(0)
    print('[4/5] Agendando teste PAPER de duas horas após o scan anterior.',flush=True)
    unit='belial-a6-2h.service'
    if subprocess.run(['systemctl','--user','is-active','--quiet',unit]).returncode==0:
        print('A6_JA_ESTA_EM_EXECUCAO_OU_AGUARDANDO=true');raise SystemExit(0)
    subprocess.run(['systemctl','--user','reset-failed',unit],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    cmd=['systemd-run','--user','--unit='+unit,'--collect','--property=Type=exec','--property=TimeoutStopSec=150','--working-directory='+str(destination),'--setenv=PYTHONDONTWRITEBYTECODE=1','--setenv=PYTHONPATH='+str(destination),'--setenv=PATH='+os.environ.get('PATH','/usr/bin:/bin')]
    for key in ('DISPLAY','WAYLAND_DISPLAY','XAUTHORITY'):
        if os.environ.get(key):cmd.append('--setenv='+key+'='+os.environ[key])
    cmd += [sys.executable,'-B','-m','a6.run','--output',str(downloads)]
    downloads.mkdir(parents=True,exist_ok=True);run(cmd)
    print('[5/5] Serviço iniciado. Pode fechar o terminal; a execução continua.',flush=True)
    print('O cronômetro de 2h começa após preparação, testes Rust e GPU. Enquanto A51R estiver ativo, A6 aguarda.',flush=True)
    print('Resultado: /home/hobit/Downloads/BELIAL_A6_2H_RESULTADO_*.zip',flush=True)
    print('Acompanhar: journalctl --user -u belial-a6-2h.service -f',flush=True)
    print('BELIAL_A6_INSTALLED=true; ORDERS=false; LIVE_TEST_NOT_YET_COMPLETED',flush=True)

